import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.BXzK3EA4.js";const u=JSON.parse('{"title":"Traffic and Latency Monitoring","description":"","frontmatter":{},"headers":[],"relativePath":"new-features/traffic-latency-monitor.md","filePath":"new-features/traffic-latency-monitor.md"}'),n={name:"new-features/traffic-latency-monitor.md"};function i(s,e,d,c,l,f){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="traffic-and-latency-monitoring" tabindex="-1">Traffic and Latency Monitoring <a class="header-anchor" href="#traffic-and-latency-monitoring" aria-label="Permalink to &quot;Traffic and Latency Monitoring&quot;">​</a></h1><p>Tradeboard provides separate views for HTTP traffic metadata and measured API/order latency.</p><h3 id="traffic-monitor" tabindex="-1">Traffic Monitor <a class="header-anchor" href="#traffic-monitor" aria-label="Permalink to &quot;Traffic Monitor&quot;">​</a></h3><p>Open <strong>Logs &gt; Traffic</strong> or visit <code>/logs/traffic</code>.</p><p>The traffic table stores:</p><ul><li>timestamp;</li><li>client IP;</li><li>HTTP method and path;</li><li>response status;</li><li>middleware duration;</li><li>request host;</li><li>an unhandled error field, when present.</li></ul><p>It does <strong>not</strong> store request bodies, response bodies, headers, user agents, or a processing timeline. This avoids persisting API keys and order payloads in the traffic table.</p><p>Summary panels show total requests, errors, average duration, and selected endpoint statistics. Filters can limit the view to all traffic or <code>/api/v1</code> traffic and to all, successful, or error responses. CSV export contains the same stored metadata.</p><p>Traffic rows live in <code>logs.db</code>. <code>TRAFFIC_LOG_RETENTION_DAYS</code> defaults to 30 days in <code>.sample.env</code>, and expired rows are purged when logging initializes.</p><h3 id="latency-monitor" tabindex="-1">Latency Monitor <a class="header-anchor" href="#latency-monitor" aria-label="Permalink to &quot;Latency Monitor&quot;">​</a></h3><p>Open the Latency page to review timing records produced by instrumented Tradeboard operations. The view is useful for comparing observed request durations and identifying changes on the actual deployment.</p><p>Latency depends on host load, network distance, broker response time, market conditions, connection reuse, and the operation being measured. The monitor reports observations; it does not guarantee an execution time or isolate exchange latency from every other component.</p><h3 id="security-boundary" tabindex="-1">Security Boundary <a class="header-anchor" href="#security-boundary" aria-label="Permalink to &quot;Security Boundary&quot;">​</a></h3><p>Both dashboards require an authenticated application session. Proxy-derived client IPs are trusted only when <code>TRUST_PROXY_HEADERS</code> is enabled; use that setting only behind a controlled reverse proxy.</p>',14)])])}const h=t(n,[["render",i]]);export{u as __pageData,h as default};
